# Mutações da 307a leva (itens mwf_14, mwf_15, mwf_16, mwf_17, mwf_18, mwf_19). Uso: python mutacoes.py mutacoes\leva307.py --carreira 2002-06-01
MUTACOES = [
    ('mwf14_sem_troca_primeira_segunda', '    exe::league_promote_and_relegate(this, comp_by_global(first), comp_by_global(second), 1, 1, -1, -1); // mwf14: the First and the Second', '    // mutation: no swap between the First and the Second', 'mwf_14 spanish chain'),
    ('mwf14_rebaixados_para_o_b2', 'exe::league_relegate_club_to_division(this, read_usize(exe::league_get_table_row(second, i)), spanish_b1_record(), 1); // mwf14: down to group B1', 'exe::league_relegate_club_to_division(this, read_usize(exe::league_get_table_row(second, i)), comp_record_of_key(KEY_CLUB_COMP_SPANISH_SECOND_DIVISION_B2), 1); // mutation: down to B2', 'mwf_14 relegated to b1'),
    ('mwf15_cfa_sem_embaralhar', 'exe::comp_util_sort_and_shuffle_top_clubs(list, n as u16 as u32, 4); // mwf15: the CFA clubs by reputation, shuffled in fours', 'exe::comp_util_sort_and_shuffle_top_clubs(list, n as u16 as u32, 1); // mutation: no shuffle', 'mwf_15 cfa up to national'),
    ('mwf16_tres_sobem_tres_descem', 'exe::league_promote_and_relegate(this, comp_by_global(a), comp_by_global(b), 1, 1, 4, 4); // mwf16: four up and four down between A and B', 'exe::league_promote_and_relegate(this, comp_by_global(a), comp_by_global(b), 1, 1, 3, 3); // mutation: three up and three down', 'mwf_16 italian chain'),
    ('mwf16_c2_sem_embaralhar', 'exe::comp_util_sort_and_shuffle_top_clubs(list, n as u16 as u32, 6); // mwf16: the C2 clubs by reputation, shuffled in sixes', 'exe::comp_util_sort_and_shuffle_top_clubs(list, n as u16 as u32, 1); // mutation: no shuffle', 'mwf_16 serie c2 up to c1'),
    ('mwf16_c1_de_sul_a_norte', 'exe::crt_qsort(list.as_mut_ptr() as usize, n as i32 as u32, 4, 0x53fd40usize); // mwf16: north to south', 'exe::crt_qsort(list.as_mut_ptr() as usize, n as i32 as u32, 4, 0x53fd40usize); list[..n as usize].reverse(); // mutation: south to north', 'mwf_16 serie c1 regrouping'),
    ('mwf17_sem_acesso_e_rebaixamento', 'chain(this.addr(), 1); // mwf17: the Italian promotion and relegation', '// mutation: no promotion and relegation', 'mwf_17 serie a rollover'),
    ('mwf18_estadio_ao_contrario', "read_usize(third.competition().addr()), 1) != 0; // mwf18: the Conference club's ground", 'read_usize(third.competition().addr()), 1) == 0; // mutation: the ground test reversed', 'mwf_18 conference exchange'),
    ('mwf19_ordem_invertida', "exe::crt_qsort(read_usize(this + 0xee), n, 4, 0x4b0780usize); // mwf19: by last season's position", 'exe::crt_qsort(read_usize(this + 0xee), n, 4, 0x4b0780usize); { let l = read_usize(this + 0xee); for a in 0..(n as usize / 2) { let (x, y) = (read_usize(l + a * 4), read_usize(l + (n as usize - 1 - a) * 4)); write_usize(l + a * 4, y); write_usize(l + (n as usize - 1 - a) * 4, x); } } // mutation: reversed', 'mwf_19 korean league cup clubs'),
    ('mwf19_grupo_a_de_tras_para_frente', 'exe::league_init_table_row(this, i as u8 as u32, read_usize(slot), 0, 0); // mwf19: row i', 'exe::league_init_table_row(this, (4 - i) as u8 as u32, read_usize(slot), 0, 0); // mutation: rows backwards', 'mwf_19 korean league cup group a'),
]
